+func TestRoomForMirrorsAdmit(t *testing.T) {
+	c := newCtl(&recPreempter{})
+	if _, err := c.Admit(Request{ID: "fg", Class: Foreground, MemMB: 1600}); err != nil {
+		t.Fatal(err)
+	}
