+// failDestroy refuses to destroy one machine.
+type failDestroy struct {
+	*vm.Manager
+	id string
+}
+
+func (f failDestroy) Destroy(ctx context.Context, id string) error {
+	if id == f.id {
+		return errors.New("disk busy")
+	}
+	return f.Manager.Destroy(ctx, id)
