+		t.Fatal(err)
+	}
+	err := <-done
+	if err == nil || !strings.HasPrefix(err.Error(), "preempted, retry: worker w ") || !strings.Contains(err.Error(), "did not fail") {
+		t.Fatalf("preempted exec = %v", err)
+	}
+}
