+		a.MemMB = DefaultMemMB
+	}
+	if a.MemMB < MinMemMB || a.MemMB > t.MaxMemMB {
+		return nil, fmt.Errorf("mem_mb must be between %d and %d", MinMemMB, t.MaxMemMB)
+	}
